class Solution:
    def goodIntegers(self, n: int) -> List[int]:
        from collections import defaultdict
        cnt = defaultdict(int)
        a = 1
        while 2 * a * a * a <= n:
            b = a
            while a * a * a + b * b * b <= n:
                cnt[a * a * a + b * b * b] += 1
                b += 1
            a += 1
        return sorted(x for x, c in cnt.items() if c >= 2)

c.cpp:
class Solution {
public:
    vector<long long> goodIntegers(long long n) {
        unordered_map<long long,int> cnt;
        for (long long a = 1; 2*a*a*a <= n; a++)
            for (long long b = a; a*a*a + b*b*b <= n; b++)
                cnt[a*a*a + b*b*b]++;
        vector<long long> res;
        for (auto& [x, c] : cnt) if (c >= 2) res.push_back(x);
        sort(res.begin(), res.end());
        return res;
    }
};

