class Solution {
    public List<Long> goodIntegers(long n) {
        Map<Long,Integer> cnt = new HashMap<>();
        for (long a = 1; 2*a*a*a <= n; a++)
            for (long b = a; a*a*a + b*b*b <= n; b++)
                cnt.merge(a*a*a + b*b*b, 1, Integer::sum);
        List<Long> res = new ArrayList<>();
        for (Map.Entry<Long,Integer> e : cnt.entrySet())
            if (e.getValue() >= 2) res.add(e.getKey());
        Collections.sort(res);
        return res;
    }
}

c.javascript:
var goodIntegers = function(n) {
    const cnt = new Map();
    for (let a = 1; 2*a*a*a <= n; a++)
        for (let b = a; a*a*a + b*b*b <= n; b++) {
            const s = a*a*a + b*b*b;
            cnt.set(s, (cnt.get(s) || 0) + 1);
        }
    return [...cnt.entries()].filter(([x, c]) => c >= 2).map(([x]) => x).sort((p, q) => p - q);
};
